{"teachable": true, "reason": "", "candidates": [
{"function": "Asking preference", "situation": "Choosing a book", "cue": "Ask which book your friend wants.", "text": "どれの本が欲しい？", "english": "Which book do you want?", "speaker": "either"},
{"function": "Offering choice", "situation": "Offering a drink", "cue": "Offer your friend a choice between water and juice.", "text": "水とこれ、どれがいい？", "english": "Water or this, which is better?", "speaker": "either"},
{"function": "Asking identification", "situation": "Identifying an object", "cue": "Ask which object is the one you saw yesterday.", "text": "あれ、昨日見たのどれ？", "english": "That one, which is the one you saw yesterday?", "speaker": "either"},
{"function": "Asking selection", "situation": "Choosing a place", "cue": "Ask your friend which place they want to go to.", "text": "どこに行きたい？どれにする？", "english": "Where do you want to go? Which one will you choose?", "speaker": "either"},
{"function": "Asking comparison", "situation": "Comparing items", "cue": "Ask which of these two items is cheaper.", "text": "これとそれ、どっちが安い？", "english": "This and that, which one is cheaper?", "speaker": "either"},
{"function": "Asking identification", "situation": "Identifying a person", "cue": "Ask which person is your friend's teacher.", "text": "あの人、先生はどれ？", "english": "That person, which one is the teacher?", "speaker": "either"}
]}

{"teachable": true, "reason": "", "candidates": [
{"function": "Asking to meet", "situation": "Suggesting meeting up again soon", "cue": "Ask your friend if they want to see each other again soon.", "text": "また会いたい？", "english": "Do you want to meet again?", "speaker": "either"},
{"function": "Answering question", "situation": "Confirming you will go somewhere again", "cue": "Tell your friend you will go to that store again.", "text": "またそこへ行くよ。", "english": "I'll go there again.", "speaker": "either"},
{"function": "Describing event", "situation": "Talking about a past event you enjoyed", "cue": "Tell your friend you want to eat that delicious food again.", "text": "またあれが食べたい。", "english": "I want to eat that again.", "speaker": "either"},
{"function": "Making plan", "situation": "Planning to do something together again", "cue": "Suggest to your friend that you do that thing together again tomorrow.", "text": "明日また一緒にする？", "english": "Shall we do it together again tomorrow?", "speaker": "either"},
{"function": "Expressing surprise", "situation": "Reacting to seeing someone unexpectedly", "cue": "Express surprise at seeing your friend there again.", "text": "あれ、また君？", "english": "Huh? You again?", "speaker": "either"},
{"function": "Offering help", "situation": "Offering to help someone with something again", "cue": "Offer to help your friend again.", "text": "また手伝おうか？", "english": "Shall I help you again?", "speaker": "either"}
]}

{"teachable": true, "reason": "", "candidates": [
{"function": "refusing offer", "situation": "shop assistant offers something extra", "cue": "A shop assistant asks if you want a bag. Say no.", "text": "いいえ、結構です。", "english": "No, thank you. / No, that's fine.", "speaker": "either"},
{"function": "denying knowledge", "situation": "someone asks if you know something", "cue": "A colleague asks if you know where the printer is. Say no.", "text": "いいえ、知りません。", "english": "No, I don't know.", "speaker": "either"},
{"function": "correcting assumption", "situation": "someone assumes something about you", "cue": "A stranger asks if you are busy today. Say no.", "text": "いいえ、暇です。", "english": "No, I am free.", "speaker": "either"},
{"function": "refusing suggestion", "situation": "friend suggests an activity", "cue": "A colleague suggests going to a movie tonight. Say no and suggest something else.", "text": "いいえ、映画はまた今度にしませんか。", "english": "No, shall we do the movie another time?", "speaker": "either"},
{"function": "denying possession", "situation": "someone asks if you have something", "cue": "A colleague asks if you have a pen. Say no.", "text": "いいえ、持っていません。", "english": "No, I don't have one.", "speaker": "either"},
{"function": "declining invitation", "situation": "someone invites you somewhere", "cue": "A colleague asks if you are going to the party. Say no.", "text": "いいえ、行きません。", "english": "No, I am not going.", "speaker": "either"}
]}

{
  "items": [
    {
      "n": 1,
      "reading": "たぶんあそこいるよ",
      "romaji": "tabun asoko iru yo"
    },
    {
      "n": 2,
      "reading": "あした、ともだちにあうとおもう。たぶん。",
      "romaji": "ashita, tomodachi ni au to omou. tabun."
    },
    {
      "n": 3,
      "reading": "たぶんいそがしいとおもうよ",
      "romaji": "tabun isogashii to omou yo"
    },
    {
      "n": 4,
      "reading": "えきまでバスにのろうよ。",
      "romaji": "eki made basu ni norou yo."
    },
    {
      "n": 5,
      "reading": "どっちのでんしゃにのればいい？",
      "romaji": "docchi no densha ni noreba ii?"
    },
    {
      "n": 6,
      "reading": "でんしゃにのるのがすきだ。",
      "romaji": "densha ni noru no ga suki da."
    },
    {
      "n": 7,
      "reading": "もうわかる？だいじょうぶ？",
      "romaji": "mou wakaru? daijoubu?"
    },
    {
      "n": 8,
      "reading": "あした、だいじょうぶ？",
      "romaji": "ashita, daijoubu?"
    },
    {
      "n": 9,
      "reading": "これ、だいじょうぶ？もつよ。",
      "romaji": "kore, daijoubu? motsu yo."
    },
    {
      "n": 10,
      "reading": "きょう、えいがをみにいこうか。",
      "romaji": "kyou, eiga o mi ni ikou ka."
    },
    {
      "n": 11,
      "reading": "どこにいきたい？",
      "romaji": "doko ni ikitai?"
    },
    {
      "n": 12,
      "reading": "でんしゃでいく？",
      "romaji": "densha de iku?"
    },
    {
      "n": 13,
      "reading": "これたべる？",
      "romaji": "kore taberu?"
    },
    {
      "n": 14,
      "reading": "もうごはんたべた？",
      "romaji": "mou gohan tabeta?"
    },
    {
      "n": 15,
      "reading": "いっしょにいこう。なにかたべよう。",
      "romaji": "issho ni ikou. nanika tabeyou."
    },
    {
      "n": 16,
      "reading": "なにがすき？",
      "romaji": "nani ga suki?"
    },
    {
      "n": 17,
      "reading": "このほんがすき。",
      "romaji": "kono hon ga suki."
    },
    {
      "n": 18,
      "reading": "どっちがすき？",
      "romaji": "docchi ga suki?"
    },
    {
      "n": 19,
      "reading": "いま、なにしてるの？",
      "romaji": "ima, nani shiteru no?"
    },
    {
      "n": 20,
      "reading": "そのえいがはなに？",
      "romaji": "sono eiga wa nani?"
    },
    {
      "n": 21,
      "reading": "なにかできることある？",
      "romaji": "nanika dekiru koto aru?"
    },
    {
      "n": 22,
      "reading": "みずのむ？",
      "romaji": "mizu nomu?"
    },
    {
      "n": 23,
      "reading": "どっちのむ？",
      "romaji": "docchi nomu?"
    },
    {
      "n": 24,
      "reading": "いま、のんでいるから、いけない。",
      "romaji": "ima, nonde iru kara, ikenai."
    },
    {
      "n": 25,
      "reading": "きょうどこいく？",
      "romaji": "kyou doko iku?"
    },
    {
      "n": 26,
      "reading": "トイレどこ？",
      "romaji": "toire doko?"
    },
    {
      "n": 27,
      "reading": "どこであう？",
      "romaji": "doko de au?"
    },
    {
      "n": 28,
      "reading": "なにかしようか？",
      "romaji": "nanika shiyou ka?"
    },
    {
      "n": 29,
      "reading": "きょうなにをする？",
      "romaji": "kyou nani o suru?"
    },
    {
      "n": 30,
      "reading": "これ、できる？",
      "romaji": "kore, dekiru?"
    }
  ]
}

